import{_ as a,o as e,c as s,a2 as n}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"02 · 关键帧","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/honey-butter/02-keyframes.md","filePath":"lab/shuangyu-fries/honey-butter/02-keyframes.md","lastUpdated":1786871523000}'),d={name:"lab/shuangyu-fries/honey-butter/02-keyframes.md"};function l(r,t,i,o,p,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="_02-·-关键帧" tabindex="-1">02 · 关键帧 <a class="header-anchor" href="#_02-·-关键帧" aria-label="Permalink to &quot;02 · 关键帧&quot;">​</a></h1><blockquote><p>蜂蜜黄油味独立创意片 ｜ P0 产品母版 + 10 张正式关键帧 ｜ 9:16 竖屏</p></blockquote><h2 id="直接结论" tabindex="-1">直接结论 <a class="header-anchor" href="#直接结论" aria-label="Permalink to &quot;直接结论&quot;">​</a></h2><p>本片先用真实产品图校准一张无包装 P0，再从 P0 生成各镜独立关键帧。关键帧只锁定产品身份、构图、光线和动作起止状态；动作、镜头运动与声音留到 Demo 和正式图生视频阶段。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>真实产品参考 → P0 身份母版 → 每镜关键帧 → Demo 动态测试 → 正式图生视频</span></span></code></pre></div><p>旧版 <code>images/黄油蜂蜜味/关键帧1.png</code> 及其衍生图只作失败对照，不再进入任何生成输入。产品身份校准沿用 <a href="./../04i-honey-butter-v2-optimization#p0-外观身份母版">04i · v2.1 的 P0 规则</a>。</p><h2 id="输入资产" tabindex="-1">输入资产 <a class="header-anchor" href="#输入资产" aria-label="Permalink to &quot;输入资产&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资产</th><th>路径</th><th>用途</th><th>使用边界</th></tr></thead><tbody><tr><td>真实产品参考</td><td><code>images/薯条脆实拍.jpg</code></td><td>锁定长宽比、锥度、自然弯曲、缺口和表面粗糙度</td><td>不继承番茄红挂粉、白底和堆叠构图</td></tr><tr><td>蜂蜜黄油包装图</td><td><code>images/薯条脆-蜂蜜黄油味.jpg</code></td><td>判断奶油黄、浅金和少量琥珀配色</td><td>不作为无包装镜头输入，不让模型复制文字和插画</td></tr><tr><td>包装工程文件</td><td><code>images/薯条脆蜂蜜黄油味包装工程文件.jpg</code></td><td>后期包装合成</td><td>只在落版后期使用</td></tr><tr><td>P0 产品母版</td><td>通过审核后补路径</td><td>全片唯一外观身份参考</td><td>不继承 P0 背景、机位和景深</td></tr><tr><td>M0 断面参考</td><td>待补</td><td>锁定断口组织</td><td>只参考断面，不继承手部和拍摄背景</td></tr></tbody></table><h2 id="输出清单与顺序" tabindex="-1">输出清单与顺序 <a class="header-anchor" href="#输出清单与顺序" aria-label="Permalink to &quot;输出清单与顺序&quot;">​</a></h2><p>所有图片保持同一批次的原生 <code>9:16</code> 尺寸；同一动态的首尾帧必须完全同尺寸。</p><table tabindex="0"><thead><tr><th style="text-align:right;">顺序</th><th>文件名</th><th>作用</th><th>输入</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td><code>p0-蜂蜜黄油产品母版.jpeg</code></td><td>全片产品身份</td><td>真实产品参考</td></tr><tr><td style="text-align:right;">2</td><td><code>kf01-出题背景.jpeg</code></td><td>镜头 01 开场底图</td><td>P0；包装后期合成</td></tr><tr><td style="text-align:right;">3</td><td><code>kf02a-单根折断首帧.jpeg</code></td><td>A 声纹首帧</td><td>P0</td></tr><tr><td style="text-align:right;">4</td><td><code>kf02b-单根折断尾帧.jpeg</code></td><td>A 声纹尾帧</td><td>KF02A + P0 + M0</td></tr><tr><td style="text-align:right;">5</td><td><code>kf03a-双根折断首帧.jpeg</code></td><td>B 声纹首帧</td><td>P0</td></tr><tr><td style="text-align:right;">6</td><td><code>kf03b-双根折断尾帧.jpeg</code></td><td>B 声纹尾帧</td><td>KF03A + P0 + M0</td></tr><tr><td style="text-align:right;">7</td><td><code>kf04a-咬下首帧.jpeg</code></td><td>C 声纹首帧</td><td>P0</td></tr><tr><td style="text-align:right;">8</td><td><code>kf04b-咬下尾帧.jpeg</code></td><td>C 声纹尾帧</td><td>KF04A + P0 + M0</td></tr><tr><td style="text-align:right;">9</td><td><code>kf05-作答界面底图.jpeg</code></td><td>波形和选项后期底图</td><td>P0</td></tr><tr><td style="text-align:right;">10</td><td><code>kf08-断面证据.jpeg</code></td><td>答案后的产品证据</td><td>P0 + M0</td></tr><tr><td style="text-align:right;">11</td><td><code>kf09-产品落版背景.jpeg</code></td><td>终稿包装后期合成底图</td><td>P0</td></tr></tbody></table><p>镜头 06 的 remix 直接复用 KF02B、KF03B、KF04B 和 KF08，不另造产品身份。镜头 07 复用 KF05 底图，只在后期改变波形和答案。</p><h2 id="p0-固定身份块" tabindex="-1">P0 固定身份块 <a class="header-anchor" href="#p0-固定身份块" aria-label="Permalink to &quot;P0 固定身份块&quot;">​</a></h2><p>以下内容写入所有含产品的关键帧 Prompt。修改构图时，不删除或弱化。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上传的 P0 是唯一产品外观母版。严格保持同一产品族的厚切但细长比例、</span></span>
<span class="line"><span>轻微自然弯曲、细微粗细变化、略微收尖的端部、不均匀缺角与稳定刚性轮廓。</span></span>
<span class="line"><span>底色为自然浅金色，外覆一层薄而干爽的奶油黄色调味粉，只有极少琥珀色细颗粒；</span></span>
<span class="line"><span>表面哑光、细密粗粝，具有轻微起伏和细小裂隙。不得继承 P0 的背景、机位或景深。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Preserve the uploaded P0 as the sole external product-identity master. Keep the exact slender</span></span>
<span class="line"><span>thick-cut proportion, subtle natural taper and bends, chipped irregular edges, pale-golden potato</span></span>
<span class="line"><span>base, thin dry creamy-yellow seasoning and compact matte food texture in every frame.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Exclude: oversized rectangular bar, extruded puff stick, corn puff, wafer, biscuit, bread stick,</span></span>
<span class="line"><span>capsule shape, cylinder, rounded ends, uniform foam cells, wet glaze, syrup, oil film, plastic gloss,</span></span>
<span class="line"><span>red seasoning, text, packaging, logo, watermark and UI overlay.</span></span></code></pre></div><h2 id="关键帧构图指令" tabindex="-1">关键帧构图指令 <a class="header-anchor" href="#关键帧构图指令" aria-label="Permalink to &quot;关键帧构图指令&quot;">​</a></h2><h3 id="kf01-·-出题背景" tabindex="-1">KF01 · 出题背景 <a class="header-anchor" href="#kf01-·-出题背景" aria-label="Permalink to &quot;KF01 · 出题背景&quot;">​</a></h3><p>奶油白自然影棚，画面下半部预留蜂蜜黄油味杯装包装的合成位置，杯口上方露出三根与 P0 完全一致的产品；上半部保持安静留白，供后期加入问题。正面略俯视，等效 50mm，柔和侧光，背景不过曝。生成图中不出现包装、文字、波形或 UI。</p><h3 id="kf02a-kf02b-·-单根折断" tabindex="-1">KF02A / KF02B · 单根折断 <a class="header-anchor" href="#kf02a-kf02b-·-单根折断" aria-label="Permalink to &quot;KF02A / KF02B · 单根折断&quot;">​</a></h3><ul><li><strong>首帧</strong>：一根 P0 横向占画面宽度约 72%，两侧只出现窄小夹具或最少量指尖，中央完整、笔直、无遮挡。</li><li><strong>尾帧</strong>：保持机位、比例、夹持位置和光线不变；产品只在中央断开一次，两段沿水平轴分开 10–15mm，断面匹配 M0，碎屑控制在 5–8 枚。</li><li><strong>排除</strong>：手掌、额外手指、弯曲软化、重复断裂、巨大孔洞、碎屑爆炸。</li></ul><h3 id="kf03a-kf03b-·-双根折断" tabindex="-1">KF03A / KF03B · 双根折断 <a class="header-anchor" href="#kf03a-kf03b-·-双根折断" aria-label="Permalink to &quot;KF03A / KF03B · 双根折断&quot;">​</a></h3><ul><li><strong>首帧</strong>：两根 P0 上下平行，间距约一根产品宽度，四个端点均在画面内，断点错开少量距离。</li><li><strong>尾帧</strong>：两根分别断开，断裂位置与碎屑不完全对称，保留自然的先后层次；产品数量、长度和粗细守恒。</li><li><strong>排除</strong>：两根融合、复制同一断口、同步爆炸、第三根产品、产品交叉遮挡。</li></ul><h3 id="kf04a-kf04b-·-咬下" tabindex="-1">KF04A / KF04B · 咬下 <a class="header-anchor" href="#kf04a-kf04b-·-咬下" aria-label="Permalink to &quot;KF04A / KF04B · 咬下&quot;">​</a></h3><ul><li><strong>首帧</strong>：只生成同一人物的下半张脸侧面，一根 P0 停在唇前约 8mm；人物肤色自然，背景包装仅保留模糊色块，不生成可读文字。</li><li><strong>尾帧</strong>：保持人物、机位和产品比例，产品前端被咬掉一小段，断口匹配 M0；嘴部自然闭合，不出现夸张表情或口腔细节。</li><li><strong>排除</strong>：完整人脸、额外牙齿、嘴部变形、产品穿模、咀嚼黏液、伪包装文字。</li></ul><h3 id="kf05-·-作答界面底图" tabindex="-1">KF05 · 作答界面底图 <a class="header-anchor" href="#kf05-·-作答界面底图" aria-label="Permalink to &quot;KF05 · 作答界面底图&quot;">​</a></h3><p>中央只保留一根垂直静止的 P0，奶油白背景，左右亮度均衡，上方和两侧留出版式空间。A / B / C、问题和真实波形全部后期添加，关键帧不生成任何图形或文字。</p><h3 id="kf08-·-断面证据" tabindex="-1">KF08 · 断面证据 <a class="header-anchor" href="#kf08-·-断面证据" aria-label="Permalink to &quot;KF08 · 断面证据&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use the approved P0 as the external product-identity reference and M0 as the strict fracture-material</span></span>
<span class="line"><span>reference. One pale-golden honey-butter potato crisp has just snapped. One irregular fracture face points</span></span>
<span class="line"><span>toward the camera and occupies about one third of the vertical frame. Preserve the exact P0 thickness,</span></span>
<span class="line"><span>dry matte surface and sparse creamy-yellow seasoning. Match M0&#39;s irregular compact dehydrated-potato</span></span>
<span class="line"><span>cells, mixed pore sizes, thin broken walls and locally dense tissue. The product makes only a subtle</span></span>
<span class="line"><span>three-quarter turn; camera and light remain locked.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>100mm macro lens, shallow depth of field, soft side backlight, restrained cream-white and pale-golden</span></span>
<span class="line"><span>palette, vertical 9:16, photorealistic commercial food image, no text, no logo, no packaging.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Exclude bread fibers, sponge, regular honeycomb, wafer layers, extruded foam, oversized holes, wet crumbs,</span></span>
<span class="line"><span>oil gloss, honey liquid, butter liquid, explosion, glass, metal, glowing particles, cartoon and watermark.</span></span></code></pre></div><h3 id="kf09-·-产品落版背景" tabindex="-1">KF09 · 产品落版背景 <a class="header-anchor" href="#kf09-·-产品落版背景" aria-label="Permalink to &quot;KF09 · 产品落版背景&quot;">​</a></h3><p>暖奶油白台面，右侧黄金分割位置预留终稿杯装包装，前景三根 P0 形成稳定放射构图，左侧保留品牌和核心文案区。只生成产品、台面、接触阴影和少量自然碎屑；包装、logo、中文与口味名全部后期合成。</p><h2 id="选片与失败回退" tabindex="-1">选片与失败回退 <a class="header-anchor" href="#选片与失败回退" aria-label="Permalink to &quot;选片与失败回退&quot;">​</a></h2><ol><li>先审 P0；产品身份不过，不生成任何镜头关键帧。</li><li>再审 KF02A / B；单根断裂不过，不扩展到双根和咬下。</li><li>手部或嘴部连续三轮不稳定时，Demo 降级为夹具断裂和产品碰撞，不用模型硬做复杂人体。</li><li>M0 缺失时，KF02B、KF03B、KF04B 和 KF08 不做断面大特写，只用侧面远景表达动作。</li><li>包装永远后期合成；任何模型生成的中文、logo 或杯身插画直接废弃。</li></ol><h2 id="本步审核" tabindex="-1">本步审核 <a class="header-anchor" href="#本步审核" aria-label="Permalink to &quot;本步审核&quot;">​</a></h2><ul><li>[ ] P0 与真实产品并排时可认作同一产品族</li><li>[ ] P0 和 10 张关键帧的画幅、尺寸、色温与产品身份统一</li><li>[ ] 首尾帧的机位、比例、光向和背景完全一致</li><li>[ ] A / B / C 的动作差异清楚，但产品没有换形</li><li>[ ] 断面有 M0 依据，不是面包、海绵或膨化泡孔</li><li>[ ] 关键帧不生成文字、波形、logo 和终稿包装</li></ul><hr><p><strong>上一步</strong> ← <a href="./01-creative">01 · 创意</a> ｜ <strong>下一步</strong> → <a href="./03-demo-preview">03 · Demo 预览</a></p>`,36)])])}const u=a(d,[["render",l]]);export{g as __pageData,u as default};
